import parse

# Test case-insensitive findall with word pattern using with_pattern
@parse.with_pattern(r'\w+')
def word_converter(s):
    return s.upper()

extra_types = {'word': word_converter}

result = list(parse.findall('{word}', 'Hello world hello WORLD', extra_types=extra_types))
print('Default:', [r.named['word'] for r in result])

result = list(parse.findall('{word}', 'Hello world hello WORLD', extra_types=extra_types, case_sensitive=False))
print('case_sensitive=False:', [r.named['word'] for r in result])
EOF
